end

function M.refresh()
  update_now()
end

function M.enable()
  vim.api.nvim_clear_autocmds({ group = AUG })

  debounced = Debounce.new(function(winid, bufnr)
    if_still_valid(winid, bufnr, update_now)
  end, CC().debounce_ms or 40)

  Autocmd.create({ "CursorMoved" }, update_debounced, {
    group = AUG,
    desc = "Cword occurrences: update on movement",
  })
  Autocmd.create({ "CursorMovedI" }, update_debounced, {
    group = AUG,
    desc = "Cword occurrences: update on movement (insert)",
  })
  Autocmd.create({ "BufEnter", "BufWinEnter", "WinScrolled" }, update_now, {
    group = AUG,
    desc = "Cword occurrences: update on view/window changes",
  })
  Autocmd.create({ "TextChanged", "TextChangedI" }, update_debounced, {
    group = AUG,
    desc = "Cword occurrences: update on edits",
  })
  Autocmd.create({ "BufLeave", "WinLeave" }, clear_all, {
    group = AUG,
    desc = "Cword occurrences: clear when leaving",
  })
  Autocmd.create({ "InsertEnter" }, function()
    if not CC().in_insert then
      clear_all()
    end
  end, {
    group = AUG,
    desc = "Cword occurrences: clear on insert (if configured)",
  })

  update_now()
end

function M.enable(_cfg)
  local aug = State.get_augroup("CWord", true)

  if not State.is_enabled("current_word") then
    -- Feature disabled: ensure match is cleared
    pcall(clear_match)
    return
  end

  Autocmd.create({ "CursorMoved" }, M.update, {
    group = aug,
    desc = "Underline current word (window-local)",
  })

  Autocmd.create({ "InsertEnter", "BufLeave", "WinLeave" }, clear_match, {
    group = aug,
    desc = "Clear current-word underline",
  })
end

function M.enable_yank()
  local aug = State.get_augroup("Flash", true)

  Autocmd.create("TextYankPost", function()
    local on_yank = (vim.hl and vim.hl.on_yank) or vim.highlight.on_yank
    on_yank({ higroup = "YankFlash", timeout = 150, on_visual = true })
  end, {
    group = aug,
    desc = "Flash yanked text region",
  })
end

function M.clear_cache(win)
  State.clear_win_mode(win)
end

function M.enable(_cfg)
  local aug = State.get_augroup("TermPalette", true)

  if not State.is_enabled("terminal_palette") then
    return
  end

  Autocmd.create("TermOpen", M.apply, {
    group = aug,
    desc = "Apply terminal-specific palette",
  })
end

function M.ensure_autocmds()
  vim.api.nvim_clear_autocmds({ group = AUG_PATHCACHE })
  Autocmd.create({ "BufEnter", "BufFilePost" }, function(args)
    M.refresh_buffer_cache(args.buf)
  end, {
    group = AUG_PATHCACHE,
    desc = "Prime repo path cache per buffer",
  })
  Autocmd.create("DirChanged", function()
    -- CWD changed: refresh current buffer cache
    M.refresh_buffer_cache(0)
  end, {
    group = AUG_PATHCACHE,
    desc = "Refresh repo path cache on :cd/:tcd",
  })
end

function M.is_large(bufnr, cfg)
  local limit = cfg.large_file_kb or 5000
  return M.exceeds(bufnr, limit)
end

function M.is_large_for_feature(bufnr, feature_limit, cfg)
  local limit = feature_limit or cfg.large_file_kb or 5000
  return M.exceeds(bufnr, limit)
end

function M.std_skip(bufnr)
  return M.buffer_is_ui_like(M.build_matchers(C.cfg.skip), bufnr)
end

function M.role()
  return role
end

function M.is(r)
  return role == r
end
